import{_ as a,C as i,o as n,c as s,a2 as t,E as r}from"./chunks/framework.qEx7tieT.js";const _=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),c={name:"guide/index.md"};function d(l,e,h,p,m,u){const o=i("MosaicViewer");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Mosaic is a file format for <strong>incremental collaboration on geometric, structured data</strong>. Many data sources may be combined to form a bigger composed picture, but in the composition they <strong>retain their identity and lineage</strong>.</p><p>It takes lessons from, and addresses shortcomings of, modern data patterns from <em>USD</em>, <em>ECS</em>, <em>JSON</em> and <em>glTF</em>, and combines them into a single flexible data system. Mosaic:</p><ul><li>is unopinionated on your data</li><li>can serialize &amp; validate any data type with JSON Schema component schemas</li><li>allows people to collaborate on that data through file exchange or API</li><li>takes an ECS approach to decoupling data from use cases</li><li>elevates parent-child relationships to allow for geometric assembly reuse</li><li>supports semantic typing through native inheritance</li></ul>',4)),r(o,{example:"helmet",caption:"A scene importing a model — two archives, one placing the other."}),e[1]||(e[1]=t('<div class="warning custom-block"><p class="custom-block-title">Status</p><p>Mosaic is pre-1.0 and in active development. Expect breaking changes to both the schema and the generated code layout.</p></div><h2 id="the-repository" tabindex="-1">The repository <a class="header-anchor" href="#the-repository" aria-label="Permalink to &quot;The repository&quot;">​</a></h2><p>This repository holds the format&#39;s specification and the tooling used to work with it:</p><ul><li><strong><code>src</code></strong> — the format definition, written in <a href="https://typespec.io" target="_blank" rel="noreferrer">TypeSpec</a>, which emits the canonical JSON Schema.</li><li><strong><code>standard</code></strong> — the emitted JSON Schema, checked in so consumers can use it without running the toolchain.</li><li><strong><code>src/code-gen</code></strong> — a CLI that turns Mosaic component schemas into typed TypeScript or C# classes.</li><li><strong><code>sdk</code></strong> — runtime libraries (in progress), the <code>mosaic</code> CLI, and <code>sdk/scenarios</code>, where what a user actually does is written in prose and the test beside it is generated from that.</li></ul>',4))])}const f=a(c,[["render",d]]);export{_ as __pageData,f as default};
